Object.assign(PHRASES.kn, {"Ask CareLens": "CareLens ಅನ್ನು ಕೇಳಿ", "CareLens assistant": "CareLens ಸಹಾಯಕ", "Open the CareLens assistant": "CareLens ಸಹಾಯಕವನ್ನು ತೆರೆಯಿರಿ", "Open full assistant": "ಪೂರ್ಣ ಸಹಾಯಕವನ್ನು ತೆರೆಯಿರಿ", "Close assistant": "ಸಹಾಯಕವನ್ನು ಮುಚ್ಚಿ", "Voice language": "ಧ್ವನಿ ಭಾಷೆ", "How can I help?": "ನಾನು ಹೇಗೆ ಸಹಾಯ ಮಾಡಲಿ?", "Ask by typing or tap the microphone. I can summarise or read out your report in English, Hindi or Kannada.": "ಟೈಪ್ ಮಾಡಿ ಕೇಳಿ ಅಥವಾ ಮೈಕ್ರೋಫೋನ್ ಒತ್ತಿ. ನಿಮ್ಮ ವರದಿಯ ಸಾರಾಂಶವನ್ನು ಅಥವಾ ಅದನ್ನು ಇಂಗ್ಲಿಷ್, ಹಿಂದಿ ಅಥವಾ ಕನ್ನಡದಲ್ಲಿ ಓದಿ ಹೇಳಬಲ್ಲೆ.", "Summarise my latest report": "ನನ್ನ ಇತ್ತೀಚಿನ ವರದಿಯ ಸಾರಾಂಶ ನೀಡಿ", "Read my report aloud": "ನನ್ನ ವರದಿಯನ್ನು ಓದಿ ಹೇಳಿ", "Summarise this document": "ಈ ದಾಖಲೆಯ ಸಾರಾಂಶ ನೀಡಿ", "Read this document aloud": "ಈ ದಾಖಲೆಯನ್ನು ಓದಿ ಹೇಳಿ", "Listen": "ಕೇಳಿ", "Stop": "ನಿಲ್ಲಿಸಿ", "Speak": "ಮಾತನಾಡಿ", "Stop listening": "ಆಲಿಸುವುದನ್ನು ನಿಲ್ಲಿಸಿ", "Listening…": "ಆಲಿಸುತ್ತಿದ್ದೇನೆ…", "Ask or speak your question…": "ನಿಮ್ಮ ಪ್ರಶ್ನೆಯನ್ನು ಬರೆಯಿರಿ ಅಥವಾ ಹೇಳಿ…", "Read replies aloud": "ಉತ್ತರಗಳನ್ನು ಓದಿ ಹೇಳಿ", "Explains your records. It doesn’t diagnose or replace your doctor.": "ನಿಮ್ಮ ದಾಖಲೆಗಳನ್ನು ವಿವರಿಸುತ್ತದೆ. ಇದು ರೋಗನಿರ್ಣಯ ಮಾಡುವುದಿಲ್ಲ, ವೈದ್ಯರಿಗೆ ಪರ್ಯಾಯವಲ್ಲ.", "AI isn’t connected, so I can only read what your records say. Connect it in Settings for summaries and translation.": "AI ಸಂಪರ್ಕವಾಗಿಲ್ಲ, ಆದ್ದರಿಂದ ನಿಮ್ಮ ದಾಖಲೆಗಳಲ್ಲಿರುವುದನ್ನು ಮಾತ್ರ ಓದಬಲ್ಲೆ. ಸಾರಾಂಶ ಮತ್ತು ಅನುವಾದಕ್ಕೆ ಸೆಟ್ಟಿಂಗ್ಸ್‌ನಲ್ಲಿ AI ಸಂಪರ್ಕಿಸಿ.", "The AI isn’t connected, so this is the report as written (not translated).": "AI ಸಂಪರ್ಕವಾಗಿಲ್ಲ, ಆದ್ದರಿಂದ ಇದು ವರದಿಯಲ್ಲಿರುವಂತೆಯೇ ಇದೆ (ಅನುವಾದವಲ್ಲ).", "This browser can’t read aloud. The answer is shown as text.": "ಈ ಬ್ರೌಸರ್ ಓದಿ ಹೇಳಲು ಸಾಧ್ಯವಿಲ್ಲ. ಉತ್ತರವನ್ನು ಪಠ್ಯದಲ್ಲಿ ತೋರಿಸಲಾಗಿದೆ.", "This device has no voice installed for": "ಈ ಸಾಧನದಲ್ಲಿ ಧ್ವನಿ ಇಲ್ಲ:", "Install one in your system language settings, or switch the language above.": "ಸಿಸ್ಟಮ್ ಭಾಷಾ ಸೆಟ್ಟಿಂಗ್ಸ್‌ನಲ್ಲಿ ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಿ, ಅಥವಾ ಮೇಲೆ ಭಾಷೆ ಬದಲಿಸಿ.", "Microphone access is blocked. Allow it in your browser, or type instead.": "ಮೈಕ್ರೋಫೋನ್ ಅನುಮತಿ ನಿರ್ಬಂಧಿತವಾಗಿದೆ. ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಅನುಮತಿಸಿ, ಅಥವಾ ಟೈಪ್ ಮಾಡಿ.", "Your browser can’t listen in this language. Try English, or type instead.": "ನಿಮ್ಮ ಬ್ರೌಸರ್ ಈ ಭಾಷೆಯಲ್ಲಿ ಆಲಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ. ಇಂಗ್ಲಿಷ್ ಪ್ರಯತ್ನಿಸಿ, ಅಥವಾ ಟೈಪ್ ಮಾಡಿ.", "Couldn’t hear that. Please try again or type.": "ಕೇಳಿಸಲಿಲ್ಲ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ ಅಥವಾ ಟೈಪ್ ಮಾಡಿ.", "Voice input isn’t supported in this browser. Chrome or Edge work best. You can still type.": "ಈ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಧ್ವನಿ ಇನ್‌ಪುಟ್ ಬೆಂಬಲಿತವಲ್ಲ. Chrome ಅಥವಾ Edge ಉತ್ತಮ. ನೀವು ಟೈಪ್ ಮಾಡಬಹುದು."});

Object.assign(PHRASES.hi, {"Security": "सुरक्षा", "Your documents and AI key are encrypted on this computer. You are signed out automatically after a period of inactivity. Recent activity on your account:": "आपके दस्तावेज़ और AI कुंजी इस कंप्यूटर पर एन्क्रिप्ट किए गए हैं। कुछ समय निष्क्रिय रहने पर आप अपने आप साइन आउट हो जाते हैं। आपके खाते की हाल की गतिविधि:", "Nothing to show yet.": "अभी दिखाने के लिए कुछ नहीं है।", "Recent security activity": "हाल की सुरक्षा गतिविधि", "If you see something you don't recognise, change your password and sign out everywhere.": "अगर कुछ अनजाना दिखे, तो पासवर्ड बदलें और हर जगह से साइन आउट करें।", "Sign out of all devices": "सभी डिवाइस से साइन आउट करें", "Signed in": "साइन इन किया", "Wrong password entered": "गलत पासवर्ड डाला गया", "Sign-in paused after too many attempts": "बहुत ज़्यादा कोशिशों के बाद साइन-इन रोका गया", "Password changed": "पासवर्ड बदला गया", "Signed out of all devices": "सभी डिवाइस से साइन आउट किया गया", "Assistant request declined for safety": "सुरक्षा कारणों से सहायक का अनुरोध रद्द किया गया", "Session ended after inactivity": "निष्क्रियता के बाद सत्र समाप्त हुआ", "At least 8 characters, not a common password": "कम से कम 8 अक्षर, आम पासवर्ड नहीं"});
Object.assign(PHRASES.kn, {"Security": "ಭದ್ರತೆ", "Your documents and AI key are encrypted on this computer. You are signed out automatically after a period of inactivity. Recent activity on your account:": "ನಿಮ್ಮ ದಾಖಲೆಗಳು ಮತ್ತು AI ಕೀ ಈ ಕಂಪ್ಯೂಟರ್‌ನಲ್ಲಿ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಆಗಿವೆ. ಸ್ವಲ್ಪ ಕಾಲ ಬಳಸದಿದ್ದರೆ ನೀವು ತಾನಾಗಿ ಸೈನ್ ಔಟ್ ಆಗುತ್ತೀರಿ. ನಿಮ್ಮ ಖಾತೆಯ ಇತ್ತೀಚಿನ ಚಟುವಟಿಕೆ:", "Nothing to show yet.": "ತೋರಿಸಲು ಇನ್ನೂ ಏನೂ ಇಲ್ಲ.", "Recent security activity": "ಇತ್ತೀಚಿನ ಭದ್ರತಾ ಚಟುವಟಿಕೆ", "If you see something you don't recognise, change your password and sign out everywhere.": "ನಿಮಗೆ ಗುರುತು ಸಿಗದ ಏನಾದರೂ ಕಂಡರೆ, ಪಾಸ್‌ವರ್ಡ್ ಬದಲಾಯಿಸಿ ಮತ್ತು ಎಲ್ಲೆಡೆಯಿಂದ ಸೈನ್ ಔಟ್ ಮಾಡಿ.", "Sign out of all devices": "ಎಲ್ಲಾ ಸಾಧನಗಳಿಂದ ಸೈನ್ ಔಟ್ ಮಾಡಿ", "Signed in": "ಸೈನ್ ಇನ್ ಆಗಿದೆ", "Wrong password entered": "ತಪ್ಪು ಪಾಸ್‌ವರ್ಡ್ ನಮೂದಿಸಲಾಗಿದೆ", "Sign-in paused after too many attempts": "ಹಲವು ಪ್ರಯತ್ನಗಳ ನಂತರ ಸೈನ್-ಇನ್ ನಿಲ್ಲಿಸಲಾಗಿದೆ", "Password changed": "ಪಾಸ್‌ವರ್ಡ್ ಬದಲಾಯಿಸಲಾಗಿದೆ", "Signed out of all devices": "ಎಲ್ಲಾ ಸಾಧನಗಳಿಂದ ಸೈನ್ ಔಟ್ ಆಗಿದೆ", "Assistant request declined for safety": "ಸುರಕ್ಷತೆಗಾಗಿ ಸಹಾಯಕ ವಿನಂತಿಯನ್ನು ತಿರಸ್ಕರಿಸಲಾಗಿದೆ", "Session ended after inactivity": "ನಿಷ್ಕ್ರಿಯತೆಯ ನಂತರ ಸೆಷನ್ ಮುಗಿದಿದೆ", "At least 8 characters, not a common password": "ಕನಿಷ್ಠ 8 ಅಕ್ಷರಗಳು, ಸಾಮಾನ್ಯ ಪಾಸ್‌ವರ್ಡ್ ಅಲ್ಲ"});

// Language the interface is currently shown in. Set by AuthContext so plain helpers (tr) and <T> agree.
let current = 'en';
export const setLang = (lang) => { current = lang || 'en'; };
export const tr = (text, lang = current) => PHRASES[lang]?.[text] ?? text;

// Translate a menu key (home, health, ...) or any English phrase; falls back to English.
export const makeT = (lang) => (key) => STRINGS[lang]?.[key] ?? STRINGS.en[key] ?? PHRASES[lang]?.[key] ?? key;
